code.cpp:
class Solution {
public:
    int maximumGain(string s, int x, int y) {
        int n = s.size();
        int score = 0;

        char hi1, hi2, lo1, lo2;
        int hiVal, loVal;
        if (x >= y) {
            hi1 = 'a'; hi2 = 'b'; hiVal = x;
            lo1 = 'b'; lo2 = 'a'; loVal = y;
        } else {
            hi1 = 'b'; hi2 = 'a'; hiVal = y;
            lo1 = 'a'; lo2 = 'b'; loVal = x;
        }

        // First pass: remove the higher-value pair
        int w = 0;
        for (int i = 0; i < n; i++) {
            if (w > 0 && s[w - 1] == hi1 && s[i] == hi2) {
                w--;
                score += hiVal;
            } else {
                s[w++] = s[i];
            }
        }

        // Second pass: remove the lower-value pair on s[0..w)
        int w2 = 0;
        for (int i = 0; i < w; i++) {
            if (w2 > 0 && s[w2 - 1] == lo1 && s[i] == lo2) {
                w2--;
                score += loVal;
            } else {
                s[w2++] = s[i];
            }
        }

        return score;
    }
};
